css:
.ceo100-sim-container {
    padding: 24px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.ceo100-sim-header {
    background: #1a2744;
    color: #ffffff;
    padding: 28px 32px;
    border-radius: 4px;
    margin-bottom: 22px;
    border-left: 6px solid #c9a86a;
}

.ceo100-sim-header-eyebrow {
    color: #c9a86a;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    font-weight: 600;
    margin-bottom: 10px;
}

.ceo100-sim-header h1 {
    font-size: 1.7rem;
    font-weight: 600;
    margin: 0 0 8px 0;
    letter-spacing: 0.01em;
}

.ceo100-sim-subtitle {
    margin: 0;
    color: #c9a86a;
    font-size: 1rem;
    font-style: italic;
    letter-spacing: 0.04em;
}

.ceo100-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    padding: 14px 20px;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    margin-bottom: 20px;
    font-size: 0.9rem;
    font-weight: 500;
    color: #4a5568;
    flex-wrap: wrap;
    gap: 10px;
}

.ceo100-sim-period-label, .ceo100-sim-day-label {
    display: flex;
    gap: 7px;
    align-items: baseline;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.78rem;
}

.ceo100-sim-period-label span:nth-child(2),
.ceo100-sim-day-label span:nth-child(2) {
    color: #1a2744;
    font-weight: 700;
    font-size: 1.15rem;
    text-transform: none;
    letter-spacing: 0;
}

.ceo100-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
}

.ceo100-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-top: 3px solid #6b7280;
    border-radius: 4px;
    padding: 16px 18px;
    transition: transform 0.18s ease;
}

.ceo100-sim-kpi-card:hover {
    transform: translateY(-2px);
}

.ceo100-sim-kpi-positive { border-top-color: #2d6a4f; }
.ceo100-sim-kpi-warning  { border-top-color: #c9821f; }
.ceo100-sim-kpi-score {
    border-top: none;
    background: #1a2744;
    color: #ffffff;
    border-color: #1a2744;
    position: relative;
}
.ceo100-sim-kpi-score::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: #c9a86a;
    border-radius: 4px 4px 0 0;
}

.ceo100-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: #6b7280;
    margin-bottom: 8px;
    font-weight: 600;
}

.ceo100-sim-kpi-score .ceo100-sim-kpi-label { color: #c9a86a; }

.ceo100-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #1a2744;
    line-height: 1.05;
}

.ceo100-sim-kpi-score .ceo100-sim-kpi-value { color: #ffffff; }

.ceo100-sim-briefing-panel {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-left: 5px solid #1a2744;
    border-radius: 4px;
    padding: 22px 26px;
    margin-bottom: 22px;
}

.ceo100-sim-section-title {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #1a2744;
    font-weight: 700;
    margin-bottom: 14px;
}

.ceo100-sim-briefing-context {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #c9821f;
    font-weight: 700;
    margin-bottom: 8px;
}

.ceo100-sim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.65;
    color: #2d3748;
}

.ceo100-sim-decisions {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 24px 26px;
    margin-bottom: 22px;
}

.ceo100-sim-allocation-block, .ceo100-sim-posture-block {
    margin-bottom: 24px;
}

.ceo100-sim-posture-block { margin-bottom: 0; }

.ceo100-sim-block-title {
    font-size: 1rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
}

.ceo100-sim-block-hint {
    font-size: 0.85rem;
    color: #6b7280;
    margin-bottom: 14px;
    line-height: 1.55;
}

.ceo100-sim-allocation-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 10px;
    margin-bottom: 12px;
}

.ceo100-sim-alloc-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #f4f5f7;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 10px 14px;
    gap: 10px;
}

.ceo100-sim-alloc-row label {
    font-size: 0.85rem;
    color: #2d3748;
    margin: 0;
    font-weight: 500;
    flex: 1;
}

.ceo100-sim-alloc-controls {
    display: flex;
    align-items: center;
    gap: 6px;
}

.ceo100-sim-alloc-ideal {
    font-size: 0.72rem;
    color: #6b7280;
    background: #e6e9ef;
    border-radius: 3px;
    padding: 2px 6px;
    font-weight: 600;
    min-width: 30px;
    text-align: center;
}

.ceo100-sim-alloc-input {
    width: 64px;
    padding: 6px 8px;
    background: #ffffff;
    border: 1px solid #c0c8d4;
    border-radius: 3px;
    color: #1a2744;
    font-weight: 600;
    text-align: right;
    font-size: 0.95rem;
}

.ceo100-sim-alloc-pct {
    font-size: 0.85rem;
    color: #6b7280;
    font-weight: 600;
}

.ceo100-sim-total-row {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    align-items: baseline;
    padding: 10px 16px;
    background: #eef0f4;
    border-radius: 3px;
    font-weight: 600;
    color: #1a2744;
    font-size: 0.9rem;
}

.ceo100-sim-total-value {
    font-size: 1.25rem;
    color: #1a2744;
    min-width: 36px;
    text-align: right;
}

.ceo100-sim-total-value.ceo100-sim-total-error { color: #b8312f; }
.ceo100-sim-total-value.ceo100-sim-total-ok    { color: #2d6a4f; }

.ceo100-sim-posture-select {
    width: 100%;
    padding: 11px 14px;
    background: #ffffff;
    border: 1px solid #c0c8d4;
    color: #1a2744;
    border-radius: 4px;
    font-size: 0.95rem;
    font-weight: 500;
}

.ceo100-sim-posture-select option {
    background: #ffffff;
    color: #1a2744;
    padding: 8px;
}

.ceo100-sim-buttons {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
    flex-wrap: wrap;
}

.ceo100-sim-submit-btn {
    background: #1a2744 !important;
    border-color: #1a2744 !important;
    color: #ffffff !important;
    padding: 12px 30px;
    font-weight: 600;
    letter-spacing: 0.03em;
    border-radius: 4px;
    text-transform: uppercase;
    font-size: 0.85rem;
}

.ceo100-sim-submit-btn:hover {
    background: #2c3e60 !important;
    border-color: #2c3e60 !important;
}

.ceo100-sim-undo-btn {
    border-radius: 4px;
    padding: 10px 18px;
}

.ceo100-sim-hint {
    background: #fef9e7;
    border: 1px solid #ecd081;
    border-left: 4px solid #c9821f;
    border-radius: 4px;
    padding: 14px 18px;
    color: #5b441a;
    font-size: 0.9rem;
    line-height: 1.55;
    margin-bottom: 22px;
    display: none;
}

.ceo100-sim-hint.ceo100-sim-hint-visible { display: block; }

.ceo100-sim-conversations, .ceo100-sim-history {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 22px 26px;
    margin-bottom: 22px;
}

.ceo100-sim-conv-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 8px;
}

.ceo100-sim-conv-row {
    display: flex;
    justify-content: space-between;
    background: #f4f5f7;
    border-radius: 3px;
    padding: 10px 14px;
    font-size: 0.88rem;
    color: #2d3748;
}

.ceo100-sim-conv-row span:last-child {
    font-weight: 700;
    color: #1a2744;
}

.ceo100-sim-history table {
    width: 100%;
    font-size: 0.85rem;
    border-collapse: collapse;
}

.ceo100-sim-history table th {
    background: #1a2744;
    color: #ffffff;
    padding: 10px 12px;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
    text-align: left;
}

.ceo100-sim-history table td {
    padding: 9px 12px;
    border-bottom: 1px solid #e2e7ef;
    color: #2d3748;
}

.ceo100-sim-history table tr:nth-child(even) td { background: #f8f9fb; }

.ceo100-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(380px, 1fr));
    gap: 18px;
    margin-bottom: 24px;
}

.ceo100-sim-chart-card {
    background: #ffffff;
    border: 1px solid #d8dde6;
    border-radius: 4px;
    padding: 20px;
    height: 320px;
    position: relative;
}

@media (max-width: 768px) {
    .ceo100-sim-container { padding: 14px; }
    .ceo100-sim-header { padding: 20px 22px; }
    .ceo100-sim-header h1 { font-size: 1.35rem; }
    .ceo100-sim-kpi-value { font-size: 1.6rem; }
    .ceo100-sim-decisions { padding: 16px; }
    .ceo100-sim-briefing-panel { padding: 16px 18px; }
    .ceo100-sim-charts { grid-template-columns: 1fr; }
    .ceo100-sim-chart-card { height: 280px; }
}


/* v1.1.0 additions: accessible focus ring + completion summary */
.ceo100-sim-container :is(select, input, button):focus-visible { outline: 3px solid #c9a227; outline-offset: 2px; }
.ceo100-completion { padding: 8px 4px; text-align: center; }
.ceo100-completion-title { margin: 0 0 12px; font-size: 1.4rem; }
.ceo100-completion-score { margin: 6px 0 16px; }
.ceo100-completion-score .acs-num { font-size: 2.6rem; font-weight: 700; }
.ceo100-completion-score .acs-max { font-size: 1.1rem; opacity: .7; margin-left: 2px; }
.ceo100-completion-score .acs-cap { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; opacity: .7; margin-top: 2px; }
.ceo100-completion-kpis { display: flex; gap: 14px; justify-content: center; margin: 12px 0 16px; flex-wrap: wrap; }
.ceo100-completion-kpis .ack { border: 1px solid rgba(150,150,150,0.35); border-radius: 10px; padding: 10px 16px; min-width: 112px; }
.ceo100-completion-kpis .ack-label { font-size: .68rem; text-transform: uppercase; letter-spacing: .05em; opacity: .7; margin-bottom: 4px; }
.ceo100-completion-kpis .ack-value { font-size: 1.4rem; font-weight: 600; }
.ceo100-completion-rating { margin: 10px auto; max-width: 580px; line-height: 1.5; }
.ceo100-completion-takeaways { text-align: left; max-width: 660px; margin: 14px auto 0; }
.ceo100-completion-takeaways h4 { font-size: .95rem; margin: 0 0 8px; }
.ceo100-completion-takeaways ul { margin: 0; padding-left: 20px; }
.ceo100-completion-takeaways li { margin-bottom: 6px; line-height: 1.45; }
.ceo100-completion-thanks { font-size: .85rem; opacity: .75; margin-top: 16px; }

