(function() {
    'use strict';

    class CEOFirst100Adapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The CEO First 100 Days`;
            this.version = '1.1.0';

            this.IDEAL_KEYS = ['cabinet', 'skip', 'frontline', 'customer', 'board', 'ecosystem'];

            this.ROUNDS = [
                {
                    day: '1-10',
                    contextKey: 'r1_context',
                    briefingKey: 'r1_briefing',
                    postureTitleKey: 'r1_posture_title',
                    postureHintKey: 'r1_posture_hint',
                    options: [
                        { val: 'cabinet_only',           i18n: 'r1_o1', score: 20 },
                        { val: 'shadow_audit_only',      i18n: 'r1_o2', score: 55 },
                        { val: 'parallel_track',         i18n: 'r1_o3', score: 100 }
                    ],
                    ideal: { cabinet: 30, skip: 15, frontline: 10, customer: 10, board: 25, ecosystem: 10 },
                    bestPosture: 'parallel_track'
                },
                {
                    day: '11-20',
                    contextKey: 'r2_context',
                    briefingKey: 'r2_briefing',
                    postureTitleKey: 'r2_posture_title',
                    postureHintKey: 'r2_posture_hint',
                    options: [
                        { val: 'respond_with_vision',          i18n: 'r2_o1', score: 10 },
                        { val: 'silent_no_defense',            i18n: 'r2_o2', score: 45 },
                        { val: 'deflect_with_diagnostic',      i18n: 'r2_o3', score: 100 }
                    ],
                    ideal: { cabinet: 25, skip: 20, frontline: 15, customer: 10, board: 20, ecosystem: 10 },
                    bestPosture: 'deflect_with_diagnostic'
                },
                {
                    day: '21-30',
                    contextKey: 'r3_context',
                    briefingKey: 'r3_briefing',
                    postureTitleKey: 'r3_posture_title',
                    postureHintKey: 'r3_posture_hint',
                    options: [
                        { val: 'reaffirm_12pct',           i18n: 'r3_o1', score: 10 },
                        { val: 'reject_12pct_publicly',    i18n: 'r3_o2', score: 30 },
                        { val: 'defer_with_date',          i18n: 'r3_o3', score: 100 }
                    ],
                    ideal: { cabinet: 20, skip: 20, frontline: 25, customer: 15, board: 10, ecosystem: 10 },
                    bestPosture: 'defer_with_date'
                },
                {
                    day: '31-40',
                    contextKey: 'r4_context',
                    briefingKey: 'r4_briefing',
                    postureTitleKey: 'r4_posture_title',
                    postureHintKey: 'r4_posture_hint',
                    options: [
                        { val: 'pivot_publicly',         i18n: 'r4_o1', score: 15 },
                        { val: 'ignore_quiros',          i18n: 'r4_o2', score: 10 },
                        { val: 'triangulate_quietly',    i18n: 'r4_o3', score: 100 }
                    ],
                    ideal: { cabinet: 20, skip: 20, frontline: 20, customer: 20, board: 10, ecosystem: 10 },
                    bestPosture: 'triangulate_quietly'
                },
                {
                    day: '41-50',
                    contextKey: 'r5_context',
                    briefingKey: 'r5_briefing',
                    postureTitleKey: 'r5_posture_title',
                    postureHintKey: 'r5_posture_hint',
                    options: [
                        { val: 'approve_sap',           i18n: 'r5_o1', score: 15 },
                        { val: 'cancel_sap',            i18n: 'r5_o2', score: 30 },
                        { val: 'defer_sap_pending',     i18n: 'r5_o3', score: 100 }
                    ],
                    ideal: { cabinet: 25, skip: 20, frontline: 20, customer: 15, board: 10, ecosystem: 10 },
                    bestPosture: 'defer_sap_pending'
                },
                {
                    day: '51-60',
                    contextKey: 'r6_context',
                    briefingKey: 'r6_briefing',
                    postureTitleKey: 'r6_posture_title',
                    postureHintKey: 'r6_posture_hint',
                    options: [
                        { val: 'vision_townhall',        i18n: 'r6_o1', score: 10 },
                        { val: 'skip_townhall',          i18n: 'r6_o2', score: 40 },
                        { val: 'listening_summary',      i18n: 'r6_o3', score: 100 }
                    ],
                    ideal: { cabinet: 15, skip: 25, frontline: 20, customer: 15, board: 15, ecosystem: 10 },
                    bestPosture: 'listening_summary'
                },
                {
                    day: '61-70',
                    contextKey: 'r7_context',
                    briefingKey: 'r7_briefing',
                    postureTitleKey: 'r7_posture_title',
                    postureHintKey: 'r7_posture_hint',
                    options: [
                        { val: 'promote_interim',        i18n: 'r7_o1', score: 20 },
                        { val: 'defer_cfo_to_100',       i18n: 'r7_o2', score: 25 },
                        { val: 'external_search_now',    i18n: 'r7_o3', score: 100 }
                    ],
                    ideal: { cabinet: 20, skip: 15, frontline: 15, customer: 25, board: 15, ecosystem: 10 },
                    bestPosture: 'external_search_now'
                },
                {
                    day: '71-80',
                    contextKey: 'r8_context',
                    briefingKey: 'r8_briefing',
                    postureTitleKey: 'r8_posture_title',
                    postureHintKey: 'r8_posture_hint',
                    options: [
                        { val: 'skip_mexico',                i18n: 'r8_o1', score: 20 },
                        { val: 'send_renata_alone',          i18n: 'r8_o2', score: 50 },
                        { val: 'visit_mexico_personally',    i18n: 'r8_o3', score: 100 }
                    ],
                    ideal: { cabinet: 15, skip: 15, frontline: 15, customer: 30, board: 15, ecosystem: 10 },
                    bestPosture: 'visit_mexico_personally'
                },
                {
                    day: '81-87',
                    contextKey: 'r9_context',
                    briefingKey: 'r9_briefing',
                    postureTitleKey: 'r9_posture_title',
                    postureHintKey: 'r9_posture_hint',
                    options: [
                        { val: 'cabinet_sap_narrative',          i18n: 'r9_o1', score: 15 },
                        { val: 'board_growth_hypothesis',        i18n: 'r9_o2', score: 35 },
                        { val: 'diagnostic_capacity_reconfig',   i18n: 'r9_o3', score: 100 }
                    ],
                    ideal: { cabinet: 30, skip: 15, frontline: 10, customer: 15, board: 20, ecosystem: 10 },
                    bestPosture: 'diagnostic_capacity_reconfig'
                },
                {
                    day: '88-100',
                    contextKey: 'r10_context',
                    briefingKey: 'r10_briefing',
                    postureTitleKey: 'r10_posture_title',
                    postureHintKey: 'r10_posture_hint',
                    options: [
                        { val: 'vision_memo',                i18n: 'r10_o1', score: 10 },
                        { val: 'empathy_memo',               i18n: 'r10_o2', score: 15 },
                        { val: 'diagnostic_three_bets',      i18n: 'r10_o3', score: 100 }
                    ],
                    ideal: { cabinet: 25, skip: 10, frontline: 10, customer: 15, board: 30, ecosystem: 10 },
                    bestPosture: 'diagnostic_three_bets'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    diagnosticQuality: 50,
                    chairConfidence: 50,
                    analystPressure: 60,
                    cabinetTrust: 70,
                    organizationalTruth: 30,
                    compositeScore: 52,
                    convCabinet: 0,
                    convSkip: 0,
                    convFrontline: 0,
                    convCustomer: 0,
                    convBoard: 0,
                    convEcosystem: 0,
                    diagnosticHistory: [],
                    chairHistory: [],
                    analystHistory: [],
                    cabinetHistory: [],
                    truthHistory: [],
                    scoreHistory: [],
                    operationalFlags: {
                        shadowAuditCommissioned: false,
                        cfoSearchLaunched: false,
                        twelvePercentReaffirmed: false,
                        sapApproved: false,
                        visionDecreedEarly: false
                    }
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    cabinet: 25,
                    skip: 20,
                    frontline: 15,
                    customer: 15,
                    board: 15,
                    ecosystem: 10,
                    posture: 'parallel_track'
                };
            }
            this._renderRound(state);
        }

        validateDecisions(decisions) {
            var ids = ['cabinet', 'skip', 'frontline', 'customer', 'board', 'ecosystem'];
            var inputIds = {
                cabinet: 'cabinetInput',
                skip: 'skipInput',
                frontline: 'frontlineInput',
                customer: 'customerInput',
                board: 'boardInput',
                ecosystem: 'ecosystemInput'
            };
            var total = 0;
            for (var i = 0; i < ids.length; i++) {
                var key = ids[i];
                var el = document.getElementById(inputIds[key]);
                if (el) {
                    var v = parseFloat(el.value);
                    if (isNaN(v) || v < 0) v = 0;
                    if (v > 100) v = 100;
                    decisions[key] = v;
                    total += v;
                }
            }
            if (Math.abs(total - 100) > 0.5) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('alloc_warning') + ' (' + Math.round(total) + '%)',
                    'warning'
                );
                return false;
            }
            var posSel = document.getElementById('postureInput');
            if (posSel) decisions.posture = posSel.value;
            if (!decisions.posture) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('posture_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod || 1;
            var roundIdx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var ideal = round.ideal;

            var keys = this.IDEAL_KEYS;
            var diffSum = 0;
            for (var i = 0; i < keys.length; i++) {
                diffSum += Math.abs((d[keys[i]] || 0) - ideal[keys[i]]);
            }
            var balanceScore = Math.max(0, Math.min(100, 100 - diffSum));

            var postureScore = 50;
            for (var j = 0; j < round.options.length; j++) {
                if (round.options[j].val === d.posture) {
                    postureScore = round.options[j].score;
                    break;
                }
            }

            var periodScore = Math.round(0.5 * balanceScore + 0.5 * postureScore);

            ds.convCabinet    += Math.round((d.cabinet    || 0) * 0.06);
            ds.convSkip       += Math.round((d.skip       || 0) * 0.10);
            ds.convFrontline  += Math.round((d.frontline  || 0) * 0.06);
            ds.convCustomer   += Math.round((d.customer   || 0) * 0.06);
            ds.convBoard      += Math.round((d.board      || 0) * 0.05);
            ds.convEcosystem  += Math.round((d.ecosystem  || 0) * 0.06);

            var deltaDiagnostic = (balanceScore - 50) * 0.25 + (postureScore - 50) * 0.20;
            ds.diagnosticQuality = this._clamp(ds.diagnosticQuality + deltaDiagnostic, 0, 100);

            var deltaChair = 0;
            if (d.posture === round.bestPosture) deltaChair += 6;
            if (postureScore <= 20) deltaChair -= 8;

            if (period === 1 && (d.posture === 'shadow_audit_only' || d.posture === 'parallel_track')) {
                ds.operationalFlags.shadowAuditCommissioned = true;
                deltaChair += 6;
            }
            if (period === 3 && d.posture === 'reaffirm_12pct') {
                ds.operationalFlags.twelvePercentReaffirmed = true;
                deltaChair -= 10;
            }
            if (period === 5 && d.posture === 'approve_sap') {
                ds.operationalFlags.sapApproved = true;
                deltaChair -= 8;
            }
            if (period === 7 && d.posture === 'external_search_now') {
                ds.operationalFlags.cfoSearchLaunched = true;
                deltaChair += 8;
            }
            if (period === 7 && d.posture === 'defer_cfo_to_100') {
                deltaChair -= 6;
            }
            if (period === 10) {
                if (d.posture === 'diagnostic_three_bets') deltaChair += 18;
                else if (d.posture === 'vision_memo') {
                    ds.operationalFlags.visionDecreedEarly = true;
                    deltaChair -= 16;
                } else if (d.posture === 'empathy_memo') deltaChair -= 12;
            }
            ds.chairConfidence = this._clamp(ds.chairConfidence + deltaChair, 0, 100);

            var deltaAnalyst = 0;
            if (postureScore >= 90) deltaAnalyst -= 6;
            else if (postureScore <= 20) deltaAnalyst += 8;
            if (period === 2 && d.posture === 'silent_no_defense') deltaAnalyst += 6;
            if (period === 2 && d.posture === 'deflect_with_diagnostic') deltaAnalyst -= 8;
            if (period === 10 && d.posture === 'diagnostic_three_bets') deltaAnalyst -= 10;
            ds.analystPressure = this._clamp(ds.analystPressure + deltaAnalyst, 0, 100);

            var deltaCabinet = 0;
            if ((d.cabinet || 0) >= ideal.cabinet - 5 && (d.cabinet || 0) <= ideal.cabinet + 10) deltaCabinet += 3;
            if ((d.cabinet || 0) < 10) deltaCabinet -= 5;
            if (period === 1 && d.posture === 'shadow_audit_only') deltaCabinet -= 4;
            if (period === 5 && d.posture === 'cancel_sap') deltaCabinet -= 8;
            if (period === 4 && d.posture === 'pivot_publicly') deltaCabinet -= 6;
            if (period === 9 && d.posture === 'diagnostic_capacity_reconfig') deltaCabinet -= 2;
            if (d.posture === round.bestPosture && period >= 6) deltaCabinet += 2;
            ds.cabinetTrust = this._clamp(ds.cabinetTrust + deltaCabinet, 0, 100);

            var truthGain = ((d.frontline || 0) + (d.skip || 0) + (d.customer || 0) * 0.5) * 0.18;
            if (d.posture === round.bestPosture) truthGain += 3;
            if (period === 4 && d.posture === 'triangulate_quietly') truthGain += 5;
            if (period === 10 && d.posture === 'diagnostic_three_bets') truthGain += 6;
            ds.organizationalTruth = this._clamp(ds.organizationalTruth + truthGain, 0, 100);

            var composite = Math.round(
                ds.diagnosticQuality * 0.30 +
                ds.chairConfidence   * 0.25 +
                (100 - ds.analystPressure) * 0.15 +
                ds.cabinetTrust      * 0.15 +
                ds.organizationalTruth * 0.15
            );
            ds.compositeScore = composite;

            ds.diagnosticHistory.push(Math.round(ds.diagnosticQuality));
            ds.chairHistory.push(Math.round(ds.chairConfidence));
            ds.analystHistory.push(Math.round(ds.analystPressure));
            ds.cabinetHistory.push(Math.round(ds.cabinetTrust));
            ds.truthHistory.push(Math.round(ds.organizationalTruth));
            ds.scoreHistory.push(composite);

            // v1.1.0 FIX: persist a 0-100 overall score (mean of per-round composite scores) so
            // the instructor results panel (results_utils.php express_resolveDomainScore ->
            // domainState.performance.overallScore) shows a real score instead of "-". Additive.
            ds.performance = {
                overallScore: Math.round(ds.scoreHistory.reduce(function(a, b) { return a + b; }, 0) / ds.scoreHistory.length),
                finalComposite: composite
            };

            var self = this;
            setTimeout(function() {
                self._renderRound({ currentPeriod: (state.currentPeriod || 1) + 1, decisions: state.decisions });
            }, 400);

            return {
                period: period,
                day: round.day,
                balanceScore: balanceScore,
                postureScore: postureScore,
                periodScore: periodScore,
                posture: d.posture,
                cabinet: d.cabinet,
                skip: d.skip,
                frontline: d.frontline,
                customer: d.customer,
                board: d.board,
                ecosystem: d.ecosystem,
                diagnosticQuality: Math.round(ds.diagnosticQuality),
                chairConfidence: Math.round(ds.chairConfidence),
                analystPressure: Math.round(ds.analystPressure),
                cabinetTrust: Math.round(ds.cabinetTrust),
                organizationalTruth: Math.round(ds.organizationalTruth),
                compositeScore: composite
            };
        }

        _clamp(v, lo, hi) {
            return Math.max(lo, Math.min(hi, v));
        }

        _renderRound(state) {
            var period = state.currentPeriod || 1;
            var roundIdx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            var dayEl = document.getElementById('dayDisplay');
            if (dayEl) dayEl.textContent = round.day;

            var ctxEl = document.getElementById('briefingContext');
            if (ctxEl) ctxEl.textContent = t(round.contextKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var titleEl = document.getElementById('postureTitle');
            if (titleEl) titleEl.textContent = t(round.postureTitleKey);

            var hintEl = document.getElementById('postureHint');
            if (hintEl) hintEl.textContent = t(round.postureHintKey);

            var sel = document.getElementById('postureInput');
            if (sel) {
                sel.innerHTML = '';
                for (var i = 0; i < round.options.length; i++) {
                    var opt = document.createElement('option');
                    opt.value = round.options[i].val;
                    opt.textContent = t(round.options[i].i18n);
                    sel.appendChild(opt);
                }
            }

            var idealMap = round.ideal;
            var idealIds = {
                cabinet: 'idealCabinet',
                skip: 'idealSkip',
                frontline: 'idealFrontline',
                customer: 'idealCustomer',
                board: 'idealBoard',
                ecosystem: 'idealEcosystem'
            };
            for (var k in idealIds) {
                var el = document.getElementById(idealIds[k]);
                if (el) el.textContent = idealMap[k];
            }

            var inputIds = {
                cabinet: 'cabinetInput',
                skip: 'skipInput',
                frontline: 'frontlineInput',
                customer: 'customerInput',
                board: 'boardInput',
                ecosystem: 'ecosystemInput'
            };
            for (var k2 in inputIds) {
                var inp = document.getElementById(inputIds[k2]);
                if (inp) inp.value = idealMap[k2];
            }
            this._updateAllocTotal();
        }

        _updateAllocTotal() {
            var ids = ['cabinetInput','skipInput','frontlineInput','customerInput','boardInput','ecosystemInput'];
            var total = 0;
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el) {
                    var v = parseFloat(el.value);
                    if (!isNaN(v)) total += v;
                }
            }
            var disp = document.getElementById('allocTotalDisplay');
            if (disp) {
                disp.textContent = Math.round(total);
                disp.classList.remove('ceo100-sim-total-error');
                disp.classList.remove('ceo100-sim-total-ok');
                if (Math.abs(total - 100) < 0.5) disp.classList.add('ceo100-sim-total-ok');
                else disp.classList.add('ceo100-sim-total-error');
            }
        }

