        getHint(state, results) {
            if (!results) return null;
            var period = results.period;
            var ds = state.domainState || {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var flags = ds.operationalFlags || {};

            if (period === 1 && !flags.shadowAuditCommissioned) {
                return t('hint_no_shadow');
            }
            if (period === 3 && flags.twelvePercentReaffirmed) {
                return t('hint_premature_target');
            }
            if (period === 5 && flags.sapApproved) {
                return t('hint_sap_capture');
            }
            if (period === 7 && !flags.cfoSearchLaunched) {
                return t('hint_cfo_late');
            }
            if (period === 10 && flags.visionDecreedEarly) {
                return t('hint_gerstner_violation');
            }
            if (results.balanceScore < 60) {
                return t('hint_unbalanced');
            }
            if (results.postureScore < 30) {
                return t('hint_weak_posture');
            }
            if (results.compositeScore >= 75 && period >= 5) {
                return t('hint_strong_diagnosis');
            }
            return null;
        }

