        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var scores = history.map(function(r) { return (r.results && r.results.compositeScore) || 0; });
            var total = scores.reduce(function(s, v) { return s + v; }, 0);
            var avg = total / scores.length;
            var last = scores[scores.length - 1];

            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };

            var rating = t('rating_beginner');
            if (avg >= 60 && last >= 65) rating = t('rating_defensible');
            if (avg >= 75 && last >= 80) rating = t('rating_watkins');
            if (avg >= 85 && last >= 90) rating = t('rating_gerstner');

            var insights = [];
            var lastResult = history[history.length - 1].results || {};
            if (lastResult.posture === 'diagnostic_three_bets') insights.push(t('insight_memo_good'));
            else if (lastResult.posture === 'vision_memo') insights.push(t('insight_memo_vision'));
            else if (lastResult.posture === 'empathy_memo') insights.push(t('insight_memo_empathy'));

            var avgFront = history.reduce(function(s, r) { return s + ((r.results && r.results.frontline) || 0); }, 0) / history.length;
            if (avgFront < 12) insights.push(t('insight_front_low'));
            else if (avgFront >= 18) insights.push(t('insight_front_high'));

            var avgCust = history.reduce(function(s, r) { return s + ((r.results && r.results.customer) || 0); }, 0) / history.length;
            if (avgCust < 10) insights.push(t('insight_cust_low'));

            return {
                overallScore: Math.round(avg),
                totalScore: Math.round(total),
                avgScore: Math.round(avg),
                finalScore: last,
                rating: rating,
                insights: insights
            };
        }

