        formatCompletionMessage(summary) {
            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            summary = summary || {};
            var score = (summary.overallScore != null) ? summary.overallScore
                        : (summary.avgScore != null ? summary.avgScore : null);
            var avg = (summary.avgScore != null) ? summary.avgScore : 0;
            var fin = (summary.finalScore != null) ? summary.finalScore : 0;
            var rating = summary.rating || '';
            var insights = Array.isArray(summary.insights) ? summary.insights : [];
            var items = insights.map(function(s) { return '<li>' + s + '</li>'; }).join('');
            var scoreBlock = (score != null)
                ? '<div class="ceo100-completion-score"><span class="acs-num">' + score
                    + '</span><span class="acs-max">/100</span><div class="acs-cap">'
                    + t('complete_score') + '</div></div>'
                : '';
            return ''
                + '<div class="ceo100-completion">'
                +   '<h3 class="ceo100-completion-title">' + t('complete_title') + '</h3>'
                +   scoreBlock
                +   '<div class="ceo100-completion-kpis">'
                +     '<div class="ack"><div class="ack-label">' + t('complete_avg')
                +       '</div><div class="ack-value">' + avg + ' / 100</div></div>'
                +     '<div class="ack"><div class="ack-label">' + t('complete_final')
                +       '</div><div class="ack-value">' + fin + ' / 100</div></div>'
                +   '</div>'
                +   (rating ? '<p class="ceo100-completion-rating"><strong>' + t('complete_rating')
                        + ':</strong> ' + rating + '</p>' : '')
                +   (items ? '<div class="ceo100-completion-takeaways"><h4>' + t('complete_takeaways')
                        + '</h4><ul>' + items + '</ul></div>' : '')
                +   '<p class="ceo100-completion-thanks">' + t('complete_thanks') + '</p>'
                + '</div>';
        }

